The evidence points to one root cause: ts-seat-service's own method is slow, and that slowness reaches the user through travel-plan and travel2. The travel-plan filesystem growth is a side effect of its warning logs, not a fault.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT p, service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM t WHERE service_name='ts-seat-service' AND span_name='SeatController.getLeftTicketOfInterval' GROUP BY ALL ORDER BY p",
          "claim": "SeatController.getLeftTicketOfInterval p95 rose from about 11 ms normal to about 430 ms abnormal."
        },
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.p AS period, s.span_name, count(*) n, approx_quantile(s.duration,0.95)/1e6 child_p95_ms, approx_quantile(c.duration,0.95)/1e6 parent_p95_ms FROM t c JOIN t s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id AND s.p=c.p WHERE c.service_name='ts-seat-service' AND c.span_name='SeatController.getLeftTicketOfInterval' GROUP BY ALL ORDER BY 1,2",
          "claim": "Seat's slow method time has only fast children (config, order-other), so the extra time is inside its own code."
        },
        {
          "kind": "metric",
          "sql": "SELECT p, metric, round(avg(value),3) avg_v FROM (SELECT 'abn' p,* FROM abnormal_metrics UNION ALL SELECT 'norm',* FROM normal_metrics) WHERE service_name='ts-seat-service' AND metric IN ('container.cpu.usage','container.memory.usage') GROUP BY ALL ORDER BY 2,1",
          "claim": "ts-seat-service container CPU and memory stay flat between normal and abnormal periods, so no resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.p AS period, c.service_name caller_svc, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95, approx_quantile(c.duration,0.95)/1e6 caller_p95 FROM t c JOIN t s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id AND s.p=c.p WHERE s.service_name='ts-seat-service' AND c.service_name='ts-travel-plan-service' GROUP BY ALL ORDER BY 1",
          "claim": "Travel-plan calls to seat rose from about 11 ms p95 to about 855 ms p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT p, service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM t WHERE service_name='ts-travel-plan-service' AND span_name='POST /api/v1/travelplanservice/travelPlan/cheapest' GROUP BY ALL ORDER BY p",
          "claim": "User-facing travel-plan /cheapest endpoint p95 rose from about 107 ms to about 4166 ms."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT c.p AS period, c.service_name caller_svc, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95, approx_quantile(c.duration,0.95)/1e6 caller_p95 FROM t c JOIN t s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id AND s.p=c.p WHERE s.service_name='ts-seat-service' AND c.service_name='ts-travel2-service' GROUP BY ALL ORDER BY 1",
          "claim": "Travel2 calls to seat rose from about 13 ms p95 to about 430 ms p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) SELECT p, service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM t WHERE service_name='ts-travel2-service' AND span_name LIKE '%/%' GROUP BY ALL ORDER BY 2,3,1",
          "claim": "Travel2 server spans on its own HTTP endpoints are the caller-side path from which ui-dashboard reaches seat-dependent work; endpoint p95 values are shown for comparison."
        }
      ]
    }
  ]
}
